WITH matched_keys AS (SELECT txn_type, account_id FROM transactions EXCEPT SELECT txn_type, account_id FROM transactions WHERE merchant = '7-Eleven'), verified AS (SELECT s.* FROM transactions s INNER JOIN matched_keys k ON s.txn_type = k.txn_type AND s.account_id = k.account_id) SELECT CASE WHEN amount >= 3500 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, STDDEV_SAMP(amount) AS amount_stddev, SUM(CASE WHEN merchant = 'Amazon' THEN amount ELSE 0 END) AS amazon_amount, COUNT_IF(merchant = 'Grab') AS grab_events FROM verified GROUP BY CASE WHEN amount >= 3500 THEN 'HIGH' ELSE 'LOW' END ORDER BY amazon_amount DESC NULLS FIRST
